<script setup lang="ts">
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {getArticle,listArticles,previewArticle,bodyText,type AdminArticle,type ArticleVersion} from '@/api/admin-articles'
import * as api from '@/api/admin-practice'
import {blankQuestion,blankMetadata,blankClozeQuestions,blankMatchQuestions,draftChecks} from '@/practice/admin-draft'
import PracticeListeningEditor from '@/components/practice/PracticeListeningEditor.vue'
import type {ListeningData,PracticeQuestionInput} from '@/api/practice'
import {ApiError} from '@/api/client'
import {errorMessage} from '@/api/identity'
import {useAuthStore} from '@/stores/auth'
import {useAuthDialogStore} from '@/stores/auth-dialog'
import {getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {parseMatchBody} from '@/practice/match-material'
import PracticeMatchEditor from '@/components/practice/PracticeMatchEditor.vue'
import PracticeClozeEditor from '@/components/practice/PracticeClozeEditor.vue'
import PracticeReader from '@/components/practice/PracticeReader.vue'
import PracticeQuestionEditor from '@/components/practice/PracticeQuestionEditor.vue'
import PracticeQuestionOverview from '@/components/practice/PracticeQuestionOverview.vue'
import PracticePublicationChecks from '@/components/practice/PracticePublicationChecks.vue'
import PracticeAdminPreview from '@/components/practice/PracticeAdminPreview.vue'
import '@/styles/practice.css'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),login=useAuthDialogStore(),sourceRecord=ref<AdminArticle>(),sessionExpired=ref(false),record=ref<api.AdminSet>(),article=ref<ArticleVersion>(),articles=ref<AdminArticle[]>([]),articleId=ref(''),metadata=ref(blankMetadata()),questions=ref<PracticeQuestionInput[]>([blankQuestion()]),reviewed=ref<string[]>([]),sourceReviewed=ref(false),index=ref(0),onlyProblems=ref(false),busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),baseline=ref(''),metadataOpen=ref(false),serverChecks=ref<api.PublicationCheck[]>([]),conflict=ref(false),preview=ref<{article:ArticleVersion;questions:PracticeQuestionInput[];title:string;readingType?:string;wordBank?:string[]}>(),versions=ref<api.PublishedVersion[]>([]),versionPage=ref(1),versionTotal=ref(0)
const readingType=ref('DETAILED'),wordBank=ref<string[]>([]),isCloze=computed(()=>readingType.value==='CLOZE')
const listening=ref<ListeningData>({audioAssetId:null,groups:[],audioReviewed:false}),audioWorking=ref(false),isListening=computed(()=>readingType.value==='LISTENING')
const isMatch=computed(()=>readingType.value==='MATCH')
const matchParagraphs=computed(()=>parseMatchBody(ownMaterial.value?materialBody.value:article.value?bodyText(article.value):'').paragraphs)
const materialBody=ref(''),ownMaterial=computed(()=>!!record.value?.materialOnly||(!record.value&&!articleId.value))
const previewMaterial=computed<ArticleVersion|undefined>(()=>{
 if(!ownMaterial.value)return article.value
 if(!materialBody.value.trim())return undefined
 const base=article.value||{id:'',articleId:'',versionNo:0,summary:'',difficulty:'B2' as const,author:'专项题组材料',sourceType:'ORIGINAL' as const,sourceUrl:null,usageNote:'',category:{id:'',code:'',name:'专项材料'},wordCount:0,estimatedMinutes:1}
 return {...base,title:metadata.value.title||'未命名专项材料',titleZh:metadata.value.titleZh,content:{schemaVersion:1,paragraphs:materialBody.value.trim().split(/\n\s*\n/).map((text,n)=>({key:'preview-'+n,sentences:[{key:'preview-s-'+n,text}]}))}}
})
let materialCommand:{snapshot:string;requestId:string}|undefined
let relocating=false,epoch=0,disposed=false,owner=auth.user?.id
const snapshot=()=>JSON.stringify({articleId:articleId.value,articleVersionId:article.value?.id,body:ownMaterial.value?materialBody.value:undefined,metadata:metadata.value,questions:questions.value,readingType:readingType.value,wordBank:wordBank.value,...(isListening.value?{listening:listening.value}:{})}),dirty=computed(()=>snapshot()!==baseline.value),checks=computed(()=>{const local=draftChecks(metadata.value,questions.value,reviewed.value,sourceReviewed.value,{readingType:readingType.value,wordBank:wordBank.value,body:ownMaterial.value?materialBody.value:article.value?bodyText(article.value):''});if(isListening.value){if(!listening.value.audioAssetId)local.push({path:'listening.audioAssetId',questionKey:null,message:'请上传完整MP3音频'});if(!listening.value.audioReviewed)local.push({path:'listening.audioReviewed',questionKey:null,message:'尚未确认整套音频预听'});if(!listening.value.groups.length)local.push({path:'listening.groups',questionKey:null,message:'请设置套内分组'})}return dirty.value?local:[...local,...serverChecks.value.filter(s=>!local.some(l=>l.path===s.path))]})
const scope=()=>{const e=epoch,id=auth.user?.id;return()=>!disposed&&e===epoch&&id===auth.user?.id}
const sourceVersions=computed(()=>{const ids=[sourceRecord.value?.publishedVersionId,sourceRecord.value?.draftVersionId,article.value?.id].filter((id):id is string=>!!id);return [...new Set(ids)].map(id=>({id,label:id===sourceRecord.value?.publishedVersionId?'当前发布版':id===sourceRecord.value?.draftVersionId?'当前草稿版':'已关联旧版本'}))})
const current=()=>{const e=epoch,g=getGeneration(),id=auth.user?.id;return()=>!disposed&&e===epoch&&g===getGeneration()&&id===auth.user?.id}
function apply(r:api.AdminSet){sessionExpired.value=false;record.value=r;readingType.value=r.readingType;listening.value=r.listening?structuredClone(r.listening):{audioAssetId:null,groups:[],audioReviewed:false};wordBank.value=r.readingType==='CLOZE'?Array.from({length:15},(_,i)=>r.wordBank?.[i]||''):[...(r.wordBank||[])];article.value=r.article;articleId.value=r.articleId;materialBody.value=r.materialOnly?bodyText(r.article):'';metadata.value=structuredClone(r.metadata);questions.value=structuredClone(r.questions);reviewed.value=[...r.reviewedQuestionKeys];sourceReviewed.value=r.sourceReviewed;serverChecks.value=r.checks||[];baseline.value=snapshot();index.value=Math.min(index.value,questions.value.length-1);conflict.value=false}
function bankChanged(n:number,value:string){wordBank.value[n]=value;materialChanged()}
async function selectType(event:Event){const control=event.target as HTMLSelectElement,next=control.value;control.value=readingType.value;if(record.value||busy.value||next===readingType.value)return;const valid=current();if(questions.value.some(q=>q.stem||q.explanation||q.correctOption||q.options.some(Boolean))){try{await ElMessageBox.confirm('切换题型会替换尚未保存的题目结构。原文和来源保留。','切换题型',{confirmButtonText:'确认切换',cancelButtonText:'取消',autofocus:false})}catch{return}}if(!valid())return;if(next==='LISTENING'&&articleId.value){if(article.value)materialBody.value=bodyText(article.value);articleId.value='';article.value=undefined;sourceRecord.value=undefined}readingType.value=next;listening.value={audioAssetId:null,groups:[],audioReviewed:false};wordBank.value=next==='CLOZE'?Array(15).fill(''):[];questions.value=next==='CLOZE'?blankClozeQuestions():next==='MATCH'?blankMatchQuestions():[{...blankQuestion(),...(next==='LISTENING'?{type:'LISTENING' as const}:{})}];index.value=0;materialChanged()}
function materialChanged(){reviewed.value=[];changed()}
function changed(key?:string){sourceReviewed.value=false;serverChecks.value=[];if(key)reviewed.value=reviewed.value.filter(k=>k!==key);notice.value='';if(metadata.value.sourceKind==='ORIGINAL'){metadata.value.year=null;metadata.value.month=null;metadata.value.paperNo=null}}
async function load(){epoch++;const valid=current(),same=scope();loading.value=true;busy.value=false;error.value='';notice.value='';record.value=undefined;article.value=undefined;articleId.value='';sourceRecord.value=undefined;materialBody.value='';materialCommand=undefined;readingType.value='DETAILED';wordBank.value=[];questions.value=[blankQuestion()];metadata.value=blankMetadata();reviewed.value=[];sourceReviewed.value=false;serverChecks.value=[];versions.value=[];baseline.value=snapshot();metadataOpen.value=route.params.id==='new';try{if(route.params.id==='new'){const p=await listArticles(new URLSearchParams({page:'1',pageSize:'50'}));if(valid())articles.value=p.items}else{const r=await api.adminPracticeSet(String(route.params.id));if(r.subjective){baseline.value=snapshot();relocating=true;await router.replace('/admin/practice/subjective/'+r.id);return}const source=await getArticle(r.articleId);if(valid()){sourceRecord.value=source;apply(r)}}}catch(e){if(same())error.value=errorMessage(e)}finally{if(same())loading.value=false}}
async function chooseArticle(){if(!articleId.value){article.value=undefined;sourceRecord.value=undefined;changed();return;}const valid=current(),same=scope();busy.value=true;try{const a=await getArticle(articleId.value),v=await previewArticle(a.id,a.publishedVersionId||a.draftVersionId);if(valid()){sourceRecord.value=a;article.value=v;if(!metadata.value.title)metadata.value.title=v.title;if(!metadata.value.titleZh)metadata.value.titleZh=v.titleZh;changed()}}catch(e){if(same())error.value=errorMessage(e)}finally{if(same())busy.value=false}}
async function changeSourceVersion(event:Event){const control=event.target as HTMLSelectElement,id=control.value;control.value=article.value?.id||'';if(!record.value||busy.value||id===article.value?.id)return;const valid=current(),same=scope();busy.value=true;error.value='';try{const next=await previewArticle(record.value.articleId,id);if(valid()){article.value=next;reviewed.value=[];changed();notice.value='已切换文章版本，请检查题目依据并重新校对。'}}catch(e){if(same())fail(e)}finally{if(same())busy.value=false}}
function input():api.DraftInput{return {articleId:articleId.value,articleVersionId:article.value!.id,examCode:'CET4',readingType:readingType.value,wordBank:[...wordBank.value],...(isListening.value?{listening:JSON.parse(JSON.stringify(listening.value))}:{}),metadata:JSON.parse(JSON.stringify(metadata.value)),questions:questions.value.map((q,n)=>({...q,options:[...q.options],sortOrder:n})),expectedLockVersion:record.value?.lockVersion||0}}
function fail(e:unknown){error.value=errorMessage(e);sessionExpired.value=e instanceof ApiError&&e.status===401;conflict.value=e instanceof ApiError&&e.status===409;if(e instanceof ApiError&&e.fieldErrors){serverChecks.value=Object.entries(e.fieldErrors).map(([path,message])=>({path,questionKey:path.match(/^questions\[([^\]]+)\]/)?.[1]||null,message}));if(e.fieldErrors.existingSetId)error.value+='（已有题组编号 '+e.fieldErrors.existingSetId+'，请返回列表打开）'}}
async function persist():Promise<boolean>{if(!ownMaterial.value&&!article.value){error.value='请录入专项原文，或选择复用的文章';metadataOpen.value=true;return false}const valid=current(),same=scope();try{let value:api.AdminSet;if(ownMaterial.value){const data={body:materialBody.value,readingType:readingType.value,wordBank:[...wordBank.value],...(isListening.value?{listening:JSON.parse(JSON.stringify(listening.value))}:{}),metadata:JSON.parse(JSON.stringify(metadata.value)),questions:questions.value.map((q,n)=>({...q,options:[...q.options],sortOrder:n})),expectedLockVersion:record.value?.lockVersion||0};const key=JSON.stringify(data);if(materialCommand?.snapshot!==key)materialCommand={snapshot:key,requestId:crypto.randomUUID()};const payload={...data,requestId:materialCommand.requestId};value=record.value?await api.savePracticeMaterial(record.value.id,payload):await api.createPracticeMaterial(payload)}else value=record.value?await api.savePracticeSet(record.value.id,input()):await api.createPracticeSet(input());if(!valid())return false;apply(value);if(route.params.id==='new'){relocating=true;try{await router.replace('/admin/practice/'+value.id)}finally{relocating=false}}notice.value='草稿已保存';return true}catch(e){if(same())fail(e);return false}}
async function save(){if(busy.value||audioWorking.value)return;busy.value=true;error.value='';const valid=current(),same=scope();try{await persist()}finally{if(same())busy.value=false}}
async function review(key:string|undefined,checked:boolean){if(busy.value||audioWorking.value)return;busy.value=true;error.value='';const valid=current(),same=scope();try{if((dirty.value||!record.value)&&!await persist())return;if(!valid()||!record.value)return;const r=await api.reviewPracticeSet(record.value.id,record.value.lockVersion,key?'QUESTION':'SOURCE',checked,key);if(valid()){apply(r);notice.value=checked?'校对确认已保存':'校对确认已撤销'}}catch(e){if(same())fail(e)}finally{if(same())busy.value=false}}
async function reviewAudio(){if(busy.value||audioWorking.value)return;busy.value=true;const valid=current(),same=scope();try{if((dirty.value||!record.value)&&!await persist())return;if(valid()&&record.value){const r=await api.reviewPracticeSet(record.value.id,record.value.lockVersion,'AUDIO',true);if(valid())apply(r)}}catch(e){if(same())fail(e)}finally{if(same())busy.value=false}}
const bulkReviewBlocked=computed(()=>checks.value.some(c=>c.path!=='sourceReview'&&!c.path.startsWith('metadata.')&&!c.path.endsWith('.review')))
async function reviewAll(){
 if(busy.value||bulkReviewBlocked.value||questions.value.every(q=>reviewed.value.includes(q.key)))return
 const valid=current(),same=scope();busy.value=true;error.value=''
 try{
  if((dirty.value||!record.value)&&!await persist())return
  if(!valid()||!record.value)return
  try{await ElMessageBox.confirm(`确认你已核对本组全部 ${questions.value.length} 题的题目、答案和解析？本操作只记录校对确认，不自动改题或发布；来源仍需单独确认。`,'整组确认校对',{confirmButtonText:'确认已校对整组',cancelButtonText:'继续检查',autofocus:false})}catch{return}
  if(!valid()||!record.value)return
  const r=await api.reviewPracticeSet(record.value.id,record.value.lockVersion,'QUESTIONS',true)
  if(valid()){apply(r);notice.value=`整组${r.questions.length}题校对确认已保存`}
 }catch(e){if(same())fail(e)}finally{if(same())busy.value=false}
}
async function status(publish:boolean){if(busy.value||dirty.value||!record.value)return;if(publish&&checks.value.length){document.getElementById('practice-checks')?.scrollIntoView({block:'start'});return}const valid=current(),same=scope();busy.value=true;try{try{await ElMessageBox.confirm(publish?'发布将生成不可变版本，学员会看到这次已校对的内容。':'下架后停止新开始，已有练习与历史版本保留。',publish?'确认发布题组':'确认下架题组',{confirmButtonText:publish?'确认发布':'确认下架',cancelButtonText:'继续检查',autofocus:false})}catch{return}if(!valid())return;const r=await api.practiceSetStatus(record.value.id,record.value.lockVersion,publish);if(valid()){apply(r);notice.value=publish?'题组已发布':'题组已下架'}}catch(e){if(same())fail(e)}finally{if(same())busy.value=false}}
async function jump(key:string,field:string){const n=questions.value.findIndex(q=>q.key===key);if(n<0)return;index.value=n;await nextTick();if(isMatch.value){const el=document.getElementById('match-'+(['stem','correctOption','explanation','review'].includes(field)?field:'stem')+'-'+key);el?.scrollIntoView({block:'center'});el?.focus({preventScroll:true});return}if(isCloze.value){const id=field==='explanation'?'cloze-explanation-':'cloze-answer-';const el=document.getElementById(id+key);el?.scrollIntoView({block:'center'});el?.focus({preventScroll:true});return}const target=field==='review'?document.querySelector('.practice-current-question .practice-checkbox input'):document.getElementById('practice-'+(field==='options'?'options':field));target?.scrollIntoView({block:'center'});(target as HTMLElement)?.focus({preventScroll:true})}
async function checkJump(check:api.PublicationCheck){if(check.questionKey){await jump(check.questionKey,check.path.split('.').at(-1)||'stem');return}if(check.path.startsWith('listening.')){const e=document.getElementById(check.path)||document.getElementById('listening-editor');e?.scrollIntoView({block:'center'});e?.focus();return}if(check.path==='sourceReview'){document.getElementById('practice-source-review')?.focus();return}metadataOpen.value=true;await nextTick();const e=document.getElementById(check.path==='body'?'practice-material-body':check.path);e?.scrollIntoView({block:'center'});e?.focus({preventScroll:true})}
function navigate(n:number){if(!busy.value&&n>=0&&n<questions.value.length)void jump(questions.value[n]!.key,'stem')}
function reorder(d:number){const n=index.value,m=n+d;if(m<0||m>=questions.value.length)return;[questions.value[n],questions.value[m]]=[questions.value[m]!,questions.value[n]!];index.value=m;questions.value.forEach((q,i)=>q.sortOrder=i);changed()}
function add(){if(questions.value.length>=(isListening.value?50:10))return;questions.value.push({...blankQuestion(),...(isListening.value?{type:'LISTENING' as const}:{}),sortOrder:questions.value.length});index.value=questions.value.length-1;changed()}
async function remove(){if(questions.value.length<2)return;const valid=current(),same=scope(),key=questions.value[index.value]!.key;try{await ElMessageBox.confirm('从草稿移除此题，已发布版本保留。','移除题目',{confirmButtonText:'移除题目',cancelButtonText:'取消',autofocus:false});if(valid()){questions.value.splice(index.value,1);reviewed.value=reviewed.value.filter(k=>k!==key);index.value=Math.min(index.value,questions.value.length-1);changed()}}catch{}}
async function leave(){if(relocating)return true;if(busy.value||audioWorking.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('尚未保存的编辑会丢失，是否继续？','离开专项编辑',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',autofocus:false});return true}catch{return false}}
async function reload(){if(await leave())await load()}
async function discard(){if(!record.value)return;const valid=current(),same=scope();try{await ElMessageBox.confirm('恢复为已保存草稿？未保存编辑会丢失。','恢复草稿',{confirmButtonText:'确认恢复',cancelButtonText:'取消',autofocus:false});if(valid()){apply(record.value);notice.value='已恢复为保存的草稿'}}catch{}}
async function history(page=1){if(!record.value)return;const valid=current(),same=scope();try{const result=await api.adminPracticeVersions(record.value.id,page);if(valid()){versions.value=result.items;versionPage.value=page;versionTotal.value=result.total}}catch(e){if(same())fail(e)}}
async function showVersion(revision:number){if(!record.value)return;const valid=current(),same=scope();try{const v=await api.adminPracticeVersion(record.value.id,revision);if(valid())preview.value={...v,title:'已发布版本 v'+revision}}catch(e){if(same())fail(e)}}
function unload(e:BeforeUnloadEvent){if(dirty.value||busy.value){e.preventDefault();e.returnValue=''}}
function clear(){epoch++;record.value=undefined;article.value=undefined;articleId.value='';sourceRecord.value=undefined;materialBody.value='';materialCommand=undefined;readingType.value='DETAILED';wordBank.value=[];questions.value=[blankQuestion()];metadata.value=blankMetadata();reviewed.value=[];sourceReviewed.value=false;baseline.value=snapshot();busy.value=false;loading.value=false;error.value='账号状态已变化，请重新加载';preview.value=undefined}
const off=onRemoteIdentityChange(clear);watch(()=>auth.user?.id,(id)=>{if(owner!==id){owner=id;clear()}},{flush:'sync'});watch(()=>route.params.id,id=>{if(relocating&&String(id)===record.value?.id)return;void load()},{immediate:true});window.addEventListener('beforeunload',unload);onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onBeforeUnmount(()=>{disposed=true;off();window.removeEventListener('beforeunload',unload)})
</script>
<template><section class="practice-page"><RouterLink to="/admin/practice">← 返回题组列表</RouterLink><header class="practice-heading"><div><h1>{{record?'编辑专项题组':'新建专项题组'}}</h1><p>一篇原文对应一组问题，校对后直接发布到专项题库，无需另发阅读文章。</p></div><span class="practice-tag">{{record?{DRAFT:'草稿',PUBLISHED:'已发布',UNLISTED:'已下架'}[record.status]:'尚未保存'}}</span></header><p v-if="loading" role="status">正在加载题组…</p><div v-if="error" class="practice-notice practice-error" role="alert">{{error}}<button v-if="sessionExpired" @click="login.switchMode('login','请重新验证登录，本地编辑已保留');login.request(route.fullPath)">重新验证登录</button><button v-if="conflict||!article" :disabled="busy" @click="reload">加载最新题组</button></div><template v-if="!loading"><div class="practice-toolbar"><span class="practice-hint" role="status">{{notice||(dirty?'当前编辑已保留，尚未保存为草稿':'草稿已保存')}}</span><div class="practice-actions"><button :disabled="busy" class="button-primary" @click="save">保存当前编辑</button><a href="#practice-overview">题目总览</a><a href="#practice-checks">发布检查</a></div></div><details class="practice-panel practice-metadata" :open="metadataOpen" @toggle="metadataOpen=($event.target as HTMLDetailsElement).open"><summary>题组信息与来源<small>{{metadata.titleZh||metadata.title||'待填写'}} · {{metadata.sourceKind==='ORIGINAL'?'原创练习':'真题来源需核验'}}</small></summary><fieldset :disabled="busy"><label v-if="!record">关联文章<select id="article" v-model="articleId" :disabled="isListening" @change="chooseArticle"><option value="">不复用，直接录入专项原文</option><option v-for="a in articles" :key="a.id" :value="a.id">{{a.draft.titleZh||a.draft.title}} · {{a.status==='PUBLISHED'?'已发布':'草稿/下架'}}</option></select></label><label v-else-if="!ownMaterial">关联文章版本<select :value="article?.id" @change="changeSourceVersion"><option v-for="v in sourceVersions" :key="v.id" :value="v.id">{{v.label}}（{{v.id}}）</option></select></label><p v-if="record&&!ownMaterial" class="practice-hint">已关联：{{article?.titleZh||article?.title}}（v{{article?.versionNo}}）。其他文章请另建题组，旧发布版本保持独立。</p><p class="practice-hint">默认直接录入专项原文；关联已有阅读文章为可选复用，不会替它发布或下架。</p><div class="practice-meta-grid" @input="changed()" @change="changed()"><label>英文标题<input id="metadata.title" v-model="metadata.title" maxlength="200"></label><label>中文标题<input id="metadata.titleZh" v-model="metadata.titleZh" maxlength="500"></label><label v-if="metadata.sourceKind==='PAST'">考试级别<select disabled><option>四级 CET-4</option><option>六级 · 规划</option><option>考研英语一 · 规划</option><option>考研英语二 · 规划</option></select></label><label>阅读题型<select :value="readingType" :disabled="!!record" @change.stop="selectType"><option value="DETAILED">仔细阅读 · 单项选择</option><option value="CLOZE">选词填空 · 10空 / 15词</option><option value="LISTENING">整套听力 · 一份完整音频</option><option value="MATCH">长篇匹配 · 10题 / 分段原文</option></select></label><label>题目来源<select v-model="metadata.sourceKind"><option value="ORIGINAL">原创练习</option><option value="PAST">真题（须有明确来源）</option></select></label><label>文章主题<select v-model="metadata.topic"><option value="education">教育</option><option value="culture">文化</option><option value="life">生活</option><option value="technology">科技</option></select></label><template v-if="metadata.sourceKind==='PAST'"><label>考试年份<input id="metadata.year" v-model.number="metadata.year" type="number"></label><label>考试月份<input id="metadata.month" v-model.number="metadata.month" type="number" min="1" max="12"></label><label>试卷套次<input id="metadata.paperNo" v-model.number="metadata.paperNo" type="number" min="1" max="9"></label></template><label>来源名称<input id="metadata.sourceName" v-model="metadata.sourceName" maxlength="500"></label><label>来源链接（可选）<input id="metadata.sourceUrl" v-model="metadata.sourceUrl" maxlength="2000"></label></div><label @input="changed()">来源与使用说明<textarea id="metadata.usageNote" v-model="metadata.usageNote" rows="3" maxlength="2000"/></label><p class="practice-hint">原创题不填写考试时间。只录入有明确依据的真题信息，不将原创样题冒充真题。</p></fieldset></details><PracticeListeningEditor v-if="isListening" v-model="listening" :questions="questions" :busy="busy" @update:model-value="materialChanged" @review="reviewAudio" @working="audioWorking=$event"/><div class="practice-workspace"><section class="practice-panel"><template v-if="ownMaterial"><h2>题组原文</h2><p class="practice-hint">仅用于本题组，不进入外刊精读列表。原文修改后需重新校对题目。</p><p v-if="isCloze" class="practice-hint">在原文对应位置填入双花括号标记：<code v-text="'{{26}}'"></code> 至 <code v-text="'{{35}}'"></code>（各一次）。标记仅表示空位，不放答案。</p><p v-if="isMatch" class="practice-hint">每段以 [A]、[B] 等连续字母开头，段落间保留空行。同一段可以对应多道陈述，修改原文后需重新校对全部题目。</p><label>专项原文<textarea id="practice-material-body" v-model="materialBody" rows="16" maxlength="20000" :disabled="busy" @input="materialChanged" placeholder="粘贴或输入与本组问题对应的英文原文"/></label><details v-if="article"><summary>查看已保存原文</summary><PracticeReader :article="article"/></details></template><PracticeReader v-else-if="article" :article="article"/><p v-else class="practice-hint">录入专项原文，或选择复用已有文章。</p></section><PracticeMatchEditor v-if="isMatch" :questions="questions" :letters="matchParagraphs.map(p=>p.letter)" :reviewed="reviewed" :busy="busy" :index="index" @change="changed" @navigate="navigate" @review="review"/><PracticeClozeEditor v-else-if="isCloze" :questions="questions" :word-bank="wordBank" :reviewed="reviewed" :busy="busy" :index="index" @bank="bankChanged" @change="changed" @navigate="navigate" @review="review"/><PracticeQuestionEditor v-else :listening="isListening" :questions="questions" :index="index" :reviewed="reviewed" :busy="busy" v-model:only-problems="onlyProblems" @change="changed" @navigate="navigate" @reorder="reorder" @add="add" @remove="remove" @review="review"/></div><PracticeQuestionOverview :bulk-disabled="bulkReviewBlocked" @review-all="reviewAll" :word-bank="wordBank" :questions="questions" :reviewed="reviewed" :busy="busy" @jump="jump" @review="review"/><div class="practice-publication"><PracticePublicationChecks :checks="checks" :questions="questions" @jump="checkJump"/><aside class="practice-panel practice-save-panel"><h2>保存与发布</h2><p class="practice-hint">{{questions.length}}题 · 发布版本 {{record?.revision?'v'+record.revision:'尚无'}}</p><button class="button-primary" :disabled="busy" @click="save">保存草稿</button><button :disabled="busy||!previewMaterial" @click="preview={article:previewMaterial!,questions:questions,title:'当前编辑草稿',readingType:readingType,wordBank:wordBank}">预览当前草稿</button><label class="practice-checkbox"><input id="practice-source-review" type="checkbox" :checked="sourceReviewed" :disabled="busy" @change="review(undefined,($event.target as HTMLInputElement).checked)">已核对文章、来源与使用说明；题目可逐题或整组确认校对。</label><button :disabled="busy||dirty||!record" @click="status(true)">{{record?.status==='PUBLISHED'?'发布更新':'发布题组'}}</button><button v-if="record?.status==='PUBLISHED'" :disabled="busy" @click="status(false)">下架题组</button><button v-if="record" :disabled="busy" @click="discard">放弃未保存修改</button><details v-if="record?.revision" @toggle="($event.target as HTMLDetailsElement).open&&history()"><summary>历史发布版本（{{record.revision}}）</summary><div v-for="v in versions" :key="v.revision" class="practice-actions"><span>v{{v.revision}} · {{v.questions.length}}题</span><button @click="showVersion(v.revision)">预览v{{v.revision}}</button></div><button v-if="versionPage>1" @click="history(versionPage-1)">上一页版本</button><button v-if="versionPage*20<versionTotal" @click="history(versionPage+1)">下一页版本</button></details><p class="practice-hint">先保存，再逐题或整组确认校对并确认来源；改题会撤销校对。发布不会改写旧版本或用户历史。</p></aside></div></template><PracticeAdminPreview v-if="preview" v-bind="preview" @close="preview=undefined"/></section></template>
